// ¿Tiene horas la agenda de /agenda?
//
// Dos veces en un mismo día la página se quedó sin ninguna hora: primero
// porque el profesional se desasignó del tratamiento en Clinera, después
// porque la API arma la grilla del día en curso en UTC. Con tráfico pagado
// encima eso es pagar por visitas que ven "sin horas disponibles".
//
// Este nodo mira los próximos días hábiles y decide si hay que avisar. Avisa
// en los bordes —cuando se rompe y cuando se recupera— y una vez cada dos
// horas mientras siga rota, para no llenar el chat.
const resumen = $json || {};
const dias = resumen.dias || {};
const fechas = Object.keys(dias).sort();

// El día en curso no cuenta: la página no lo ofrece a propósito.
const hoy = new Date().toISOString().slice(0, 10);
const utiles = fechas.filter((f) => f > hoy);
const conHoras = utiles.filter((f) => dias[f] > 0);
// -1 es "no se pudo consultar". No es lo mismo que cero, pero si TODOS los
// días vuelven desconocidos tampoco hay agenda que ofrecer.
const desconocidos = utiles.filter((f) => dias[f] < 0);

const roto = !resumen.ok || utiles.length === 0 || conHoras.length === 0;
const primeros = utiles.slice(0, 5);
const detalle = primeros.map((f) => f.slice(5) + ': ' + (dias[f] < 0 ? '?' : dias[f])).join(' · ');

const estado = $getWorkflowStaticData('global');
const ahora = Date.now();
const DOS_HORAS = 2 * 3600000;

let avisar = false;
let texto = '';

if (roto) {
  const primeraVez = !estado.roto;
  if (primeraVez || ahora - (estado.ultimoAviso || 0) > DOS_HORAS) {
    avisar = true;
    estado.ultimoAviso = ahora;
    const desde = primeraVez ? '' :
      '\n_Sigue rota desde hace ' + Math.round((ahora - (estado.desde || ahora)) / 3600000) + ' h._';
    texto =
      '🔴 *clinera.io/agenda sin horas disponibles*\n\n' +
      'Ningún día de los próximos ' + utiles.length + ' tiene hora que ofrecer.\n' +
      (desconocidos.length ? '*Días que no se pudieron consultar:* ' + desconocidos.length + '\n' : '') +
      '*Próximos días:* ' + (detalle || '(sin datos)') + '\n\n' +
      'Lo más probable, por orden: que el profesional quedó desasignado del ' +
      'tratamiento "Reunión con Clinera" en app.clinera.io, o que se le vació el ' +
      'horario de atención en la sucursal.\n' +
      '_Con campaña activa, cada visita a /agenda está viendo "sin horas disponibles"._' + desde;
  }
  if (!estado.roto) estado.desde = ahora;
  estado.roto = true;
} else {
  if (estado.roto) {
    avisar = true;
    const horas = Math.round((ahora - (estado.desde || ahora)) / 3600000);
    texto =
      '🟢 *clinera.io/agenda volvió a tener horas*\n\n' +
      '*Días con hora:* ' + conHoras.length + ' de ' + utiles.length + '\n' +
      '*Próximos días:* ' + detalle +
      (horas ? '\n\n_Estuvo sin horas unas ' + horas + ' h._' : '');
  }
  estado.roto = false;
  estado.ultimoAviso = 0;
}

return [{ json: { roto: roto, avisar: avisar, textoChat: texto,
                  diasConHoras: conHoras.length, diasMirados: utiles.length, detalle: detalle } }];
